const url = env.get('INFLUX_URL'), org = env.get('INFLUX_ORG'), bucket = env.get('INFLUX_BUCKET'), token = env.get('INFLUX_TOKEN');
if (!url || !org || !bucket || !token) { node.error('Faltan variables INFLUX_* en el entorno'); return null; }
msg.method = 'POST';
msg.url = url + '/api/v2/write?org=' + encodeURIComponent(org) + '&bucket=' + encodeURIComponent(bucket) + '&precision=ms';
msg.headers = { 'Authorization': 'Token ' + token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'prueba_conexion,origen=nodered valor=1.5,contador=1i ' + Date.now();
return msg;

// GENERADOR DE DATOS: simula los 3 equipos (15 variables) y arma un "ciclo" de mediciones.
// Es el reemplazo en Node-RED del simulador de Python (mismas formulas, mismos rangos).
// Este nodo se ejecuta cada 5 s, pero solo genera un ciclo cuando toca segun el modo:
//   normal = una medicion cada 120 s   |   demo = una cada 15 s
// Salida 1 -> escritura en InfluxDB (medicion cruda + eventos de fallas provocadas)
// Salida 2 -> lecturas del ciclo para los indicadores y las alertas
const A = global.get('aqm');
const C = A.CATALOGO;
const ahora = Date.now();

// ---------- modo e intervalo ----------
const modo = global.get('gen_modo') || 'normal';
const intervaloS = modo === 'demo'
    ? Number(env.get('GEN_INTERVALO_DEMO_S') || C.GENERADOR.intervalo_demo_s)
    : Number(env.get('GEN_INTERVALO_S') || C.GENERADOR.intervalo_normal_s);

if (global.get('gen_pausa') === true) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'PAUSADO' });
    return null;
}

// ---------- ¿toca generar un ciclo? ----------
const ultimoTs = global.get('gen_ultimo_ts') || 0;
let ts = Math.floor(ahora / (intervaloS * 1000)) * intervaloS * 1000;   // alineado a la grilla (17:04:00, 17:06:00, ...)
if (global.get('gen_forzar') === true) {                                  // al provocar una falla se mide enseguida
    ts = Math.floor(ahora / 1000) * 1000;
    if (ts <= ultimoTs) ts = ultimoTs + 1000;
    global.set('gen_forzar', false);
} else if (ts <= ultimoTs) {
    return null;
}

// ---------- estado interno de los equipos (persistente) ----------
function nuevoEstado() {
    const fase = () => Math.random() * 2 * Math.PI;
    return {
        EQ01: { ciclo: 0, fase: fase(), anom: {}, enMarcha: true },
        EQ02: { ciclo: 0, fase: fase(), anom: {}, colmatacion: 0 },
        EQ03: { ciclo: 0, fase: fase(), anom: {}, phDesvio: 0, phDesvioCiclos: 0 }
    };
}
const st = global.get('gen_estado') || nuevoEstado();

// ---------- fallas: las pedidas por botones y las aleatorias ----------
const inyectadas = [];
(global.get('gen_cola_fallas') || []).forEach((t) => {
    st[C.ANOMALIAS[t].equipo].anom[t] = C.ANOMALIAS[t].ciclos_default;
    inyectadas.push({ tipo: t, origen: 'manual' });
});
global.set('gen_cola_fallas', []);
if (global.get('gen_aleatorio') === true && Math.random() < C.GENERADOR.prob_falla_aleatoria) {
    const tipos = Object.keys(C.ANOMALIAS);
    const t = tipos[Math.floor(Math.random() * tipos.length)];
    const eq = C.ANOMALIAS[t].equipo;
    if (!((st[eq].anom[t] || 0) > 0)) {
        st[eq].anom[t] = C.ANOMALIAS[t].ciclos_default;
        inyectadas.push({ tipo: t, origen: 'aleatoria' });
    }
}

// ---------- utilidades de senal ----------
const gauss = (sigma) => {
    let u = 0;
    while (u === 0) u = Math.random();
    return sigma * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random());
};
const uni = (a, b) => a + (b - a) * Math.random();
const sinus = (e, amp, periodo, desf) => (periodo <= 0 ? 0 : amp * Math.sin((2 * Math.PI / periodo) * e.ciclo + e.fase + (desf || 0)));
const activa = (e, t) => (e.anom[t] || 0) > 0;
const clip = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const r3 = (v) => Math.round(v * 1000) / 1000;

// Calidad del dato: 2 = bueno, 1 = dudoso (muy fuera del rango de operacion), 0 = inverosimil.
function calidad(eq, variable, v) {
    const cfg = C.EQUIPOS[eq].variables[variable];
    const lo = cfg.min_op, hi = cfg.max_op;
    const span = hi > lo ? hi - lo : 1;
    if (v >= lo - 0.5 * span && v <= hi + 0.5 * span) return 2;
    if (v >= lo - 1.5 * span && v <= hi + 1.5 * span) return 1;
    return 0;
}

// ---------- EQ01: bomba de ingreso ----------
function leerBomba(e) {
    const n = C.EQUIPOS.EQ01.variables;
    if (activa(e, 'PARADA_BOMBA')) e.enMarcha = false;                       // parada imprevista provocada
    else if (activa(e, 'CAUDAL_DROP') && Math.random() < 0.10) e.enMarcha = false;   // a veces la proteccion para la bomba
    else if (!activa(e, 'CAUDAL_DROP')) e.enMarcha = true;
    if (!e.enMarcha) {                                                       // bomba parada: todo colapsa a ~0
        return {
            CAUDAL: [Math.abs(gauss(0.4)), 2], PRESION: [Math.abs(gauss(0.05)), 2],
            CORRIENTE: [Math.abs(gauss(0.3)), 2], VIBRACION: [Math.abs(gauss(0.05)), 2], ESTADO: [0, 2]
        };
    }
    let caudal = n.CAUDAL.normal + sinus(e, 6.0, 180) + gauss(1.8);
    if (activa(e, 'CAUDAL_DROP')) caudal *= uni(0.45, 0.65);
    const desv = (caudal - n.CAUDAL.normal) / n.CAUDAL.normal;
    let presion = n.PRESION.normal - 1.2 * desv * n.PRESION.normal * 0.15 + sinus(e, 0.08, 90, 1.0) + gauss(0.06);
    if (activa(e, 'CAUDAL_DROP')) presion *= uni(0.70, 0.85);
    let corriente = n.CORRIENTE.normal * (0.55 + 0.45 * caudal / n.CAUDAL.normal) + gauss(0.7);
    if (activa(e, 'CAUDAL_DROP')) { corriente *= uni(0.80, 0.92); corriente += gauss(2.5); }
    let vib = n.VIBRACION.normal + sinus(e, 0.25, 60, 0.5) + Math.abs(gauss(0.30));
    if (activa(e, 'VIB_HIGH')) {                                             // la falla avanza cuanto mas dura
        const avance = 1 - e.anom.VIB_HIGH / Math.max(C.ANOMALIAS.VIB_HIGH.ciclos_default, 1);
        vib += 4.5 + 4.0 * avance + Math.abs(gauss(0.6));
    }
    return {
        CAUDAL: [Math.max(caudal, 0), calidad('EQ01', 'CAUDAL', caudal)],
        PRESION: [Math.max(presion, 0), calidad('EQ01', 'PRESION', presion)],
        CORRIENTE: [Math.max(corriente, 0), calidad('EQ01', 'CORRIENTE', corriente)],
        VIBRACION: [Math.max(vib, 0), calidad('EQ01', 'VIBRACION', vib)],
        ESTADO: [1, 2]
    };
}

// ---------- EQ02: filtro de arena ----------
function leerFiltro(e) {
    const n = C.EQUIPOS.EQ02.variables;
    const col = e.colmatacion;
    const turbIn = n.TURB_IN.normal + sinus(e, 2.5, 200) + Math.abs(gauss(1.2));
    let turbOut = n.TURB_OUT.normal + 0.9 * col * n.TURB_OUT.normal + 0.02 * (turbIn - n.TURB_IN.normal) + Math.abs(gauss(0.05));
    if (activa(e, 'FILTER_SAT')) turbOut += 0.6 + Math.abs(gauss(0.15));
    let presDif = n.PRES_DIF.normal + 520.0 * col + sinus(e, 12.0, 70) + gauss(8.0);
    if (activa(e, 'FILTER_SAT')) presDif += 180.0;
    const caudalFilt = n.CAUDAL_FILT.normal * (1.0 - 0.18 * Math.min(col, 1.2)) + sinus(e, 4.0, 150, 0.7) + gauss(1.5);
    const ef = clip((turbIn - Math.max(turbOut, 1e-6)) / Math.max(turbIn, 1e-6) * 100 + gauss(0.6), 0, 100);
    return {
        TURB_IN: [Math.max(turbIn, 0), calidad('EQ02', 'TURB_IN', turbIn)],
        TURB_OUT: [Math.max(turbOut, 0), calidad('EQ02', 'TURB_OUT', turbOut)],
        PRES_DIF: [Math.max(presDif, 0), calidad('EQ02', 'PRES_DIF', presDif)],
        CAUDAL_FILT: [Math.max(caudalFilt, 0), calidad('EQ02', 'CAUDAL_FILT', caudalFilt)],
        EFICIENCIA: [ef, calidad('EQ02', 'EFICIENCIA', ef)]
    };
}

// ---------- EQ03: reactor biologico ----------
function leerReactor(e) {
    const n = C.EQUIPOS.EQ03.variables;
    const temp = n.TEMP.normal + sinus(e, 3.0, 720) + gauss(0.25);
    let ph = n.PH.normal + sinus(e, 0.08, 110) + e.phDesvio + gauss(0.04);
    if (activa(e, 'PH_SPIKE')) ph += (e.ciclo % 2 === 0 ? 1 : -1) * (1.4 + Math.abs(gauss(0.2)));
    const od = n.OD.normal - 0.06 * (temp - n.TEMP.normal) + sinus(e, 0.35, 95, 1.3) + gauss(0.12);
    const cond = n.CONDUCT.normal + sinus(e, 120.0, 260) + 0.05 * e.ciclo + gauss(25.0);
    const nivel = clip(n.NIVEL.normal + sinus(e, 5.0, 130, 0.4) + gauss(0.8), 0, 100);
    return {
        PH: [ph, calidad('EQ03', 'PH', ph)],
        OD: [Math.max(od, 0), calidad('EQ03', 'OD', od)],
        TEMP: [temp, calidad('EQ03', 'TEMP', temp)],
        CONDUCT: [Math.max(cond, 0), calidad('EQ03', 'CONDUCT', cond)],
        NIVEL: [nivel, calidad('EQ03', 'NIVEL', nivel)]
    };
}

// ---------- avanzar el estado un ciclo (igual que EquipoBase.paso del simulador) ----------
function paso(e, extra) {
    e.ciclo += 1;
    Object.keys(e.anom).forEach((t) => { e.anom[t] -= 1; if (e.anom[t] <= 0) delete e.anom[t]; });
    if (extra) extra(e);
}
const pasoFiltro = (e) => {
    e.colmatacion += (1.0 / 240) * (activa(e, 'FILTER_SAT') ? 6.0 : 1.0);   // retrolavado cada 240 ciclos
    if (e.ciclo % 240 === 0) e.colmatacion = 0;
};
const pasoReactor = (e) => {
    if (e.phDesvioCiclos > 0) { e.phDesvioCiclos -= 1; if (e.phDesvioCiclos === 0) e.phDesvio = 0; }
    else if (Math.random() < 0.03) { e.phDesvio = uni(-0.35, 0.35); e.phDesvioCiclos = 3 + Math.floor(Math.random() * 6); }
};

// ---------- ciclo ----------
const modelos = { EQ01: [leerBomba, null], EQ02: [leerFiltro, pasoFiltro], EQ03: [leerReactor, pasoReactor] };
const lecturas = [];
const fallasActivas = [];
Object.keys(modelos).forEach((eq) => {
    const e = st[eq];
    Object.keys(e.anom).forEach((t) => fallasActivas.push(t));
    const crudo = modelos[eq][0](e);
    Object.keys(crudo).forEach((variable) => {
        lecturas.push({
            equipo: eq, area: C.EQUIPOS[eq].area, variable, unit: C.EQUIPOS[eq].variables[variable].unit,
            value: r3(crudo[variable][0]), quality: crudo[variable][1], ts
        });
    });
    paso(e, modelos[eq][1]);
});
global.set('gen_estado', st);
global.set('gen_ultimo_ts', ts);
global.set('gen_ciclos_total', (global.get('gen_ciclos_total') || 0) + 1);

// ---------- escritura en InfluxDB (line protocol, precision ms) ----------
const lineas = lecturas.map((l) =>
    'raw_variables,planta=' + C.PLANTA + ',area=' + l.area + ',equipo=' + l.equipo + ',variable=' + l.variable +
    ',unit=' + A.escTag(l.unit) + ',tag=' + [C.EMPRESA, C.PLANTA, l.area, l.equipo, l.variable].join('-') +
    ' value=' + l.value + ',quality=' + l.quality + 'i ' + l.ts);
inyectadas.forEach((i) => {
    const an = C.ANOMALIAS[i.tipo];
    lineas.push('events,equipo=' + an.equipo + ',event_type=ANOMALIA_INYECTADA,severity=info,motivo=' + i.tipo +
        ' value=' + an.ciclos_default + ',detalle="' + A.escStr(an.descripcion + ' (origen: ' + i.origen + ')') + '" ' + ts);
});

node.status({
    fill: fallasActivas.length ? 'red' : 'green', shape: 'dot',
    text: modo + ' ' + intervaloS + ' s | ciclo ' + global.get('gen_ciclos_total') + (fallasActivas.length ? ' | falla: ' + fallasActivas.join(',') : '') +
        (global.get('gen_aleatorio') ? ' | aleatorias' : '')
});

return [
    { payload: lineas.join('\n'), medida: 'raw_variables', ts },
    { lecturas, ts, modo, intervaloS, fallasActivas }
];

// CONTROLES DEL GENERADOR: todos los botones (inject) pasan por aca con msg.accion.
//   modo_normal | modo_demo | pausa | reanudar | aleatorio_on | aleatorio_off | falla:<NOMBRE> | reiniciar_estado
// Cambiar de modo NO requiere editar codigo ni reiniciar: se guarda en el contexto global.
const A = global.get('aqm');
const C = A.CATALOGO;
const accion = String(msg.accion || '');

if (accion === 'modo_normal' || accion === 'modo_demo') {
    global.set('gen_modo', accion === 'modo_demo' ? 'demo' : 'normal');
    global.set('gen_forzar', true);             // mide enseguida con el nuevo intervalo
    node.warn('Modo del generador: ' + global.get('gen_modo'));
} else if (accion === 'pausa') {
    global.set('gen_pausa', true);
} else if (accion === 'reanudar') {
    global.set('gen_pausa', false);
} else if (accion === 'aleatorio_on') {
    global.set('gen_aleatorio', true);
} else if (accion === 'aleatorio_off') {
    global.set('gen_aleatorio', false);
} else if (accion === 'reiniciar_estado') {
    global.set('gen_estado', null);
} else if (accion.indexOf('falla:') === 0) {
    const tipo = accion.slice(6);
    if (!C.ANOMALIAS[tipo]) { node.error('Falla desconocida: ' + tipo); return null; }
    const cola = global.get('gen_cola_fallas') || [];
    cola.push(tipo);
    global.set('gen_cola_fallas', cola);
    global.set('gen_forzar', true);             // la falla se ve en la siguiente medicion (no hay que esperar 2 minutos)
    node.warn('Falla provocada: ' + tipo + ' (' + C.ANOMALIAS[tipo].descripcion + ')');
} else {
    node.error('Accion desconocida: ' + accion);
    return null;
}

const modo = global.get('gen_modo') || 'normal';
node.status({
    fill: 'blue', shape: 'dot',
    text: 'modo ' + modo + (global.get('gen_pausa') ? ' | PAUSADO' : '') + (global.get('gen_aleatorio') ? ' | fallas aleatorias' : '')
});
return null;

// INDICADORES (KPIs): por cada ciclo del generador acumula las muestras buenas (calidad 2) en
// los 4 periodos abiertos (hora, turno, dia, semana) y escribe en InfluxDB una fila por
// KPI y periodo.
//  - La marca de tiempo de la fila es el INICIO del periodo (en UTC), calculado en hora Argentina.
//  - Mientras el periodo esta abierto la fila se reescribe (misma clave = se pisa): queda UNA sola.
//  - Cuando empieza el periodo siguiente, la fila del anterior se escribe por ultima vez con cerrado=true.
// Los acumuladores se guardan en el contexto global (en disco), asi que sobreviven a un reinicio.
const A = global.get('aqm');
const lecturas = msg.lecturas, ts = msg.ts;
if (!lecturas || !ts) return null;

const estado = global.get('kpi_estado') || {};
const cerrados = global.get('kpi_cerrados') || { dia: {} };   // KPIs de los dias ya cerrados (los usa el reporte diario)
const lineas = [];
let nCerrados = 0;

A.GRANULARIDADES.forEach((g) => {
    const inicio = A.inicioPeriodo(g, ts);
    let p = estado[g];
    if (p && p.inicio !== inicio) {                            // cambio de periodo: se cierra el anterior
        const kpisFinal = A.calcularKpis(g, p.acc);
        A.lineasKpi(g, p.inicio, kpisFinal, true).forEach((l) => lineas.push(l));
        nCerrados += 1;
        if (g === 'dia') {
            cerrados.dia[p.inicio] = kpisFinal;
            Object.keys(cerrados.dia).sort().slice(0, -10).forEach((k) => delete cerrados.dia[k]);   // guarda los ultimos 10 dias
        }
        p = null;
    }
    if (!p) p = estado[g] = { inicio, acc: {} };
    lecturas.forEach((l) => A.acumular(p.acc, l));
    A.lineasKpi(g, inicio, A.calcularKpis(g, p.acc), false).forEach((l) => lineas.push(l));   // periodo en curso
});

global.set('kpi_estado', estado);
global.set('kpi_cerrados', cerrados);
node.status({ fill: 'green', shape: 'dot', text: lineas.length + ' filas' + (nCerrados ? ' | cerro ' + nCerrados + ' periodo(s)' : '') });
return { payload: lineas.join('\n'), medida: 'kpi_values' };

// ALERTA DE BOMBA EQ01 - detector de "normal -> falla" y "falla -> normal".
// Falla critica: vibracion > 7,1 | caudal < 70 o > 175 | presion < 2,5 o > 6,5 | corriente > 65 | ESTADO < 0,5
// (los limites salen del catalogo). Se descartan solo las lecturas con calidad 0; calidad 1 y 2 valen.
// Avisa UNA vez cuando empieza la falla y UNA vez cuando se normaliza: la falla se da por terminada cuando
// la bomba estuvo ALERTA_REARME_S segundos seguidos en valores normales (por defecto 60).
// NO hay cooldown en la bomba: una falla nueva, despues de normalizarse, siempre avisa.
const A = global.get('aqm');
const rearmeS = Number(env.get('ALERTA_REARME_S') || A.CATALOGO.ALERTAS.rearme_s);
const ts = msg.ts;
const r = A.motivosBomba(msg.lecturas || []);

const est = global.get('bomba_estado') || { enFalla: false, desde: null, okDesde: null, fallas: 0 };
let evento = null;
if (r.motivos.length > 0) {
    est.okDesde = null;
    if (!est.enFalla) {                                         // paso de normal a falla: AVISAR
        est.enFalla = true;
        est.desde = ts;
        est.fallas = (est.fallas || 0) + 1;
        evento = { tipo: 'falla', ts, motivos: r.motivos, valores: r.valores };
    }
} else if (est.enFalla) {                                       // esta normal, pero venia en falla
    if (est.okDesde === null) est.okDesde = ts;
    if (ts - est.okDesde >= rearmeS * 1000) {                   // normal sostenido: cerrar la falla
        evento = { tipo: 'normalizada', ts, duracionS: Math.round((est.okDesde - est.desde) / 1000), valores: r.valores };
        est.enFalla = false;
        est.desde = null;
        est.okDesde = null;
    }
}
global.set('bomba_estado', est);
node.status(est.enFalla ? { fill: 'red', shape: 'dot', text: 'EN FALLA' + (est.okDesde ? ' (normalizando)' : '') } : { fill: 'green', shape: 'dot', text: 'normal | fallas: ' + est.fallas });
return evento ? { evento } : null;

// Convierte el evento de la bomba en: [1] mail, [2] fila en InfluxDB (measurement events).
// Los eventos de PRUEBA (boton) solo mandan mail, no escriben en la base.
const A = global.get('aqm');
const e = msg.evento;
if (!e) return null;
const marcar = e.prueba === true || global.get('marcar_prueba') !== false;   // por defecto los mails llevan [PRUEBA] mientras se desarrolla
const hora = A.fmtFecha(e.ts);
const quien = 'Bomba de ingreso EQ01 (planta PTEF, área CAPT)';
const v = e.valores || {};
const lectura = ['CAUDAL', 'PRESION', 'CORRIENTE', 'VIBRACION', 'ESTADO'].filter((k) => v[k] !== undefined).map((k) => k + ' ' + v[k]).join(' | ');

let asunto, texto, lineaEvento, clave;
if (e.tipo === 'falla') {
    const motivo = e.motivos[0].variable;
    asunto = 'FALLA: Bomba de ingreso EQ01';
    texto = 'FALLA DE BOMBA\n' + quien + '\nHora: ' + hora + '\nMotivo:\n' + e.motivos.map((m) => '- ' + m.texto).join('\n') +
        (lectura ? '\nÚltimos valores: ' + lectura : '');
    lineaEvento = 'events,equipo=EQ01,event_type=BOMBA_FALLA,severity=critical,motivo=' + A.escTag(motivo) +
        ' value=' + Number(e.motivos[0].valor) + ',detalle="' + A.escStr(e.motivos.map((m) => m.texto).join('; ')) + '" ' + e.ts;
    clave = 'BOMBA_FALLA';
} else {
    const dur = e.duracionS + ' segundos (' + Math.floor(e.duracionS / 60) + ' min ' + (e.duracionS % 60) + ' s)';
    asunto = 'NORMALIZADA: Bomba de ingreso EQ01';
    texto = 'BOMBA NORMALIZADA\n' + quien + '\nHora: ' + hora + '\nEstuvo en falla ' + dur + '.' + (lectura ? '\nÚltimos valores: ' + lectura : '');
    lineaEvento = 'events,equipo=EQ01,event_type=BOMBA_NORMALIZADA,severity=info value=' + Number(e.duracionS) +
        ',duracion_s=' + Math.round(e.duracionS) + 'i,detalle="' + A.escStr('estuvo en falla ' + e.duracionS + ' s') + '" ' + e.ts;
    clave = 'BOMBA_NORMALIZADA';
}
if (marcar) { asunto = '[PRUEBA] ' + asunto; texto = '[PRUEBA] ' + texto; }

let salidaEvento = null;
if (!e.prueba) {
    salidaEvento = { payload: lineaEvento, medida: 'events' };
    const porDia = global.get('eventos_dia') || {};
    const dia = A.fmtDia(e.ts);
    porDia[dia] = porDia[dia] || {};
    porDia[dia][clave] = (porDia[dia][clave] || 0) + 1;
    Object.keys(porDia).sort().slice(0, -10).forEach((k) => delete porDia[k]);
    global.set('eventos_dia', porDia);
}
return [{ topic: asunto, payload: texto, tipo: 'alerta' }, salidaEvento];

// Boton de prueba: arma una falla de bomba FALSA para ver como llega el mail. No escribe nada en la base.
return {
    evento: {
        tipo: msg.tipo_prueba === 'normalizada' ? 'normalizada' : 'falla', prueba: true, ts: Date.now(), duracionS: 125,
        motivos: [{ variable: 'VIBRACION', valor: 8.2, texto: 'vibración 8.2 mm/s fuera del límite crítico [- a 7,1]' }],
        valores: { CAUDAL: 118, PRESION: 4.6, CORRIENTE: 47, VIBRACION: 8.2, ESTADO: 1 }
    }
};

msg.tipo_prueba = 'normalizada';
// Boton de prueba: arma una falla de bomba FALSA para ver como llega el mail. No escribe nada en la base.
return {
    evento: {
        tipo: msg.tipo_prueba === 'normalizada' ? 'normalizada' : 'falla', prueba: true, ts: Date.now(), duracionS: 125,
        motivos: [{ variable: 'VIBRACION', valor: 8.2, texto: 'vibración 8.2 mm/s fuera del límite crítico [- a 7,1]' }],
        valores: { CAUDAL: 118, PRESION: 4.6, CORRIENTE: 47, VIBRACION: 8.2, ESTADO: 1 }
    }
};

// Interruptor de los mails: con "marcar [PRUEBA]" activado (valor por defecto) todos los avisos y reportes
// llevan [PRUEBA] en el asunto. Para la presentacion se desactiva con el boton correspondiente.
global.set('marcar_prueba', msg.accion === 'marcar_on');
node.status({ fill: 'blue', shape: 'dot', text: 'mails ' + (global.get('marcar_prueba') ? 'marcados [PRUEBA]' : 'SIN marca [PRUEBA]') });
return null;

// ALERTAS DE EQ02 (filtro) y EQ03 (reactor). La bomba EQ01 NO pasa por aca (tiene su propio flow).
// Anti-spam:
//  - se registra/avisa solo cuando una variable ENTRA en critico o en advertencia (no en cada muestra);
//  - ademas, un mail por variable como maximo cada ALERTA_COOLDOWN_S (modo demo: ALERTA_COOLDOWN_DEMO_S, 60 s);
//  - todos los criticos nuevos de un mismo ciclo van juntos en UN solo mail.
// Se aceptan lecturas de calidad 1 y 2; se descartan las de calidad 0.
// Salida 1 -> mail | salida 2 -> filas de events en InfluxDB
const A = global.get('aqm');
const C = A.CATALOGO;
const demo = msg.modo === 'demo';
const cooldownS = demo
    ? Number(env.get('ALERTA_COOLDOWN_DEMO_S') || C.ALERTAS.cooldown_demo_s)
    : Number(env.get('ALERTA_COOLDOWN_S') || C.ALERTAS.cooldown_normal_s);
const ts = msg.ts;
const estado = global.get('umbral_estado') || {};
const criticosNuevos = [];
const lineas = [];
const porDia = global.get('eventos_dia') || {};
const dia = A.fmtDia(ts);
porDia[dia] = porDia[dia] || {};

(msg.lecturas || []).filter((l) => l.equipo !== 'EQ01' && l.quality !== 0).forEach((l) => {
    const clave = l.equipo + '.' + l.variable;
    const prev = estado[clave] || { sev: null, ultimoMail: 0 };
    const sev = A.severidad(l.equipo, l.variable, l.value);
    if (sev && sev !== prev.sev && !(prev.sev === 'critical' && sev === 'warning')) {   // entro en una zona peor
        const cfg = C.EQUIPOS[l.equipo].variables[l.variable];
        const rango = cfg[sev === 'critical' ? 'critical' : 'warning'];
        const detalle = cfg.etiqueta + ' ' + l.value + ' ' + cfg.unit + ' fuera del límite ' + (sev === 'critical' ? 'crítico ' : 'de advertencia ') + A.rangoTexto(rango);
        const tipo = sev === 'critical' ? 'UMBRAL_CRITICO' : 'UMBRAL_ADVERTENCIA';
        lineas.push('events,equipo=' + l.equipo + ',event_type=' + tipo + ',severity=' + sev + ',motivo=' + l.variable +
            ' value=' + l.value + ',detalle="' + A.escStr(detalle) + '" ' + ts);
        porDia[dia][tipo] = (porDia[dia][tipo] || 0) + 1;
        if (sev === 'critical' && ts - prev.ultimoMail >= cooldownS * 1000) {
            criticosNuevos.push({ equipo: l.equipo, variable: l.variable, detalle });
            prev.ultimoMail = ts;
        }
    }
    prev.sev = sev;
    estado[clave] = prev;
});
global.set('umbral_estado', estado);
global.set('eventos_dia', porDia);

let mail = null;
if (criticosNuevos.length) {
    const marcar = global.get('marcar_prueba') !== false;
    const equipos = Array.from(new Set(criticosNuevos.map((c) => c.equipo))).join(', ');
    mail = {
        topic: (marcar ? '[PRUEBA] ' : '') + 'ALERTA CRÍTICA: ' + equipos + ' - ' + criticosNuevos.map((c) => c.variable).join(', '),
        payload: (marcar ? '[PRUEBA] ' : '') + 'ALERTA CRÍTICA\nHora: ' + A.fmtFecha(ts) + '\n' +
            criticosNuevos.map((c) => '- ' + c.equipo + '/' + c.variable + ': ' + c.detalle).join('\n') +
            '\n\n(Aviso único por variable; se vuelve a avisar como máximo cada ' + Math.round(cooldownS / 60 * 10) / 10 + ' min.)',
        tipo: 'alerta'
    };
}
node.status({ fill: lineas.length ? 'yellow' : 'green', shape: 'dot', text: (lineas.length ? lineas.length + ' evento(s) | ' : 'sin eventos | ') + 'cooldown ' + cooldownS + ' s' });
return [mail, lineas.length ? { payload: lineas.join('\n'), medida: 'events' } : null];

// REPORTE DIARIO (06:00 hora Argentina): KPIs del dia anterior y conteo de fallas, por mail.
// Los datos salen de la memoria de Node-RED (KPIs de los dias cerrados y contador de eventos por dia).
// Con msg.prueba = true arma el reporte con el DIA EN CURSO (para probar el formato) y lo marca [PRUEBA].
const A = global.get('aqm');
const ahora = Date.now();
const prueba = msg.prueba === true;
const marcar = prueba || global.get('marcar_prueba') !== false;
const diaIni = prueba ? A.inicioPeriodo('dia', ahora) : A.inicioPeriodo('dia', ahora) - 24 * 3600 * 1000;
const dia = A.fmtDia(diaIni);
const etiquetaDia = dia.split('-').reverse().join('/');

let kpis = ((global.get('kpi_cerrados') || { dia: {} }).dia || {})[diaIni];
let origenKpi = 'dia cerrado';
if (!kpis && prueba) {
    const p = (global.get('kpi_estado') || {}).dia;
    kpis = p ? A.calcularKpis('dia', p.acc) : null;
    origenKpi = 'dia en curso (parcial)';
}
kpis = kpis || [];
const ev = (global.get('eventos_dia') || {})[dia] || {};
const n = (k) => ev[k] || 0;

const filas = kpis.map((k) => '<tr><td>' + k.equipo + '</td><td>' + k.kpi + '</td><td style="text-align:right">' + String(k.value).replace('.', ',') +
    '</td><td>' + k.unit + '</td><td style="text-align:right">' + k.muestras + '</td></tr>').join('');
const tabla = kpis.length
    ? '<table border="1" cellpadding="5" cellspacing="0" style="border-collapse:collapse"><tr><th>Equipo</th><th>Indicador</th><th>Valor</th><th>Unidad</th><th>Muestras</th></tr>' + filas + '</table>'
    : '<p><i>No hay indicadores guardados para este día (Node-RED no estuvo midiendo o el día todavía no cerró).</i></p>';

const html = '<h2>Reporte diario AquaMonitor - ' + etiquetaDia + (marcar ? ' [PRUEBA]' : '') + '</h2>' +
    (prueba ? '<p><b>[PRUEBA]</b> Reporte armado con el día en curso (' + origenKpi + ').</p>' : '') +
    '<h3>Indicadores del día (por equipo)</h3>' + tabla +
    '<h3>Fallas y alertas del día</h3><ul>' +
    '<li>Fallas de la bomba EQ01: <b>' + n('BOMBA_FALLA') + '</b> (normalizaciones: ' + n('BOMBA_NORMALIZADA') + ')</li>' +
    '<li>Alertas críticas EQ02/EQ03: <b>' + n('UMBRAL_CRITICO') + '</b></li>' +
    '<li>Advertencias EQ02/EQ03: ' + n('UMBRAL_ADVERTENCIA') + '</li></ul>' +
    '<p style="color:#666">Generado el ' + A.fmtFecha(ahora) + ' (hora Argentina).</p>';
return { topic: (marcar ? '[PRUEBA] ' : '') + 'Reporte diario AquaMonitor - ' + etiquetaDia, payload: html, tipo: 'reporte' };

// Prepara la peticion de escritura a InfluxDB Cloud (ruta compatible v2, precision ms).
// El token se lee del entorno (.env) y viaja solo en el encabezado: no queda en ningun archivo.
const url = env.get('INFLUX_URL'), org = env.get('INFLUX_ORG'), bucket = env.get('INFLUX_BUCKET'), token = env.get('INFLUX_TOKEN');
if (!url || !org || !bucket || !token) { node.error('Faltan variables INFLUX_* en el entorno'); return null; }
const cuerpo = String(msg.payload || '').trim();
if (!cuerpo) return null;
return {
    method: 'POST',
    url: url.replace(/\/+$/, '') + '/api/v2/write?org=' + encodeURIComponent(org) + '&bucket=' + encodeURIComponent(bucket) + '&precision=ms',
    headers: { 'Authorization': 'Token ' + token, 'Content-Type': 'text/plain; charset=utf-8' },
    payload: cuerpo,
    lp: cuerpo,
    medida: msg.medida || '',
    nLineas: cuerpo.split('\n').length,
    _reintento: msg._reintento || 0
};

// Revisa la respuesta de InfluxDB: 204 = escrito. Si falla, reintenta hasta 2 veces (cada 10 s).
// Salida 1 -> reintento | salida 2 -> nada (queda el estado del nodo)
const ok = msg.statusCode === 204 || msg.statusCode === 200;
if (ok) {
    const n = (context.get('escrituras') || 0) + 1;
    context.set('escrituras', n);
    node.status({ fill: 'green', shape: 'dot', text: msg.nLineas + ' filas (' + msg.medida + ') | total ' + n });
    return [null, null];
}
node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + msg.statusCode + ' (' + msg.medida + ')' });
node.error('InfluxDB respondio ' + msg.statusCode + ' al escribir ' + msg.medida + ': ' + String(msg.payload).slice(0, 300));
if ((msg._reintento || 0) < 2 && msg.statusCode !== 400 && msg.statusCode !== 401 && msg.statusCode !== 403) {
    return [{ payload: msg.lp, medida: msg.medida, _reintento: (msg._reintento || 0) + 1 }, null];
}
return [null, null];

// Arma el mail con los datos del entorno (.env). Quien llama pone msg.topic (asunto), msg.payload (texto o
// HTML) y msg.tipo ('alerta' o 'reporte'). Los destinatarios y el remitente salen del entorno.
const para = msg.tipo === 'reporte' ? (env.get('REPORTE_MAIL_TO') || env.get('ALERT_MAIL_TO')) : env.get('ALERT_MAIL_TO');
if (!para) { node.error('Falta ALERT_MAIL_TO / REPORTE_MAIL_TO en el entorno'); return null; }
const n = (global.get('mails_enviados') || 0) + 1;
global.set('mails_enviados', n);
node.status({ fill: 'blue', shape: 'dot', text: 'mails pedidos desde el arranque del contador: ' + n });
return { to: para, from: env.get('ALERT_MAIL_FROM') || undefined, topic: msg.topic, payload: msg.payload, _reintento: msg._reintento || 0 };

// Si el envio falla por la red (por ejemplo ENETUNREACH al elegir una direccion IPv6 en WSL2), reintenta
// hasta 2 veces; el nodo de mail vuelve a resolver la direccion y suele elegir IPv4. Salida 1 -> espera 5 s -> reenvio.
const texto = String((msg.error && msg.error.message) || '');
if ((msg._reintento || 0) < 2 && /ENETUNREACH|ETIMEDOUT|ECONNRESET|ECONNREFUSED|EAI_AGAIN|EHOSTUNREACH/.test(texto)) {
    node.warn('Mail no enviado (' + texto.slice(0, 80) + '). Reintento ' + ((msg._reintento || 0) + 1) + ' de 2');
    return { to: msg.to, from: msg.from, topic: msg.topic, payload: msg.payload, _reintento: (msg._reintento || 0) + 1 };
}
node.error('Mail NO enviado: ' + texto.slice(0, 200));
return null;
